const H='https://old-hub.example/webhook/';
const post=b=>this.helpers.httpRequest({method:'POST',url:H+'cbs-plant-act',body:b,json:true,timeout:30000}).catch(e=>({err:String(e.message).slice(0,120)}));
const t1=await post({a:'nope',ids:[1]}),t2=await post({a:'back',ids:[]}),t3=await post({a:'extend',ids:[1]});
const f=await this.helpers.httpRequest({url:H+'cbs-actions-data?x='+Date.now(),json:true,timeout:120000});
const P=(f.items||[]).filter(i=>i.t==='plantback').map(i=>i.key+' | '+i.dtitle+' | '+i.status+' | '+i.sub+' | ids '+(i.items||[]).join(','));
return [{json:{t1,t2,t3,plant:f._plant,cards:P,counts:f.counts}}];
